    def keys(self) -> tuple[str, ...]:
        """Return column names in positional order."""
        return self.headers

    def values(self) -> tuple[str, ...]:
        """Return cell values in positional order."""
        return self.cells

    def items(self) -> tuple[tuple[str, str], ...]:
